"use client"
import React, { useState } from "react"
import { Send, Palette, Loader2 } from "lucide-react"
import { sendTelegramNotification } from "../lib/telegram"
import { PRESET_COLORS } from "../types"
import { useMutation, useQueryClient } from "@tanstack/react-query"
import axios from "axios"
import type { Note } from "../types"

interface NoteFormProps {
  onClose: () => void
}

export function NoteForm({ onClose }: NoteFormProps) {
  const [content, setContent] = useState("")
  const [author, setAuthor] = useState("")
  const [color, setColor] = useState<string>(PRESET_COLORS[0])
  const queryClient = useQueryClient()

  const { mutate: addNote, isPending: isSubmitting } = useMutation({
    mutationFn: async (newNote: { content: string; author: string; color: string }) => {
      const response = await axios.post("/api/notes", newNote)
      return response.data as Note
    },
    onSuccess: (data) => {
      // Optimistically update the cache if it doesn't already exist via Realtime
      queryClient.setQueryData<Note[]>(["notes"], (old) => {
        if (!old) return [data]
        if (old.some(n => n.id === data.id)) return old
        return [data, ...old].slice(0, 200)
      })

      // Send Telegram Notification in the background (fire and forget)
      sendTelegramNotification(data.content, data.author).catch(console.error)

      // Reset form and close
      setContent("")
      setAuthor("")
      setColor(PRESET_COLORS[0])
      onClose()
    },
    onError: (error) => {
      console.error("Error adding note: ", error)
      alert("Failed to add note. Please try again.")
    }
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!content.trim()) return

    const finalAuthor = author.trim() || "Anonymous"
    
    addNote({
      content: content.trim(),
      author: finalAuthor,
      color: color
    })
  }

  return (
    <div 
      className="form-sticky-note animate-fade-in"
      style={{ backgroundColor: color }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
        <h2 style={{ margin: 0, color: "#1e293b", fontSize: "1.5rem" }}>Create New Note</h2>
        <button 
          type="button"
          onClick={onClose}
          className="close-btn"
          title="Close note"
        >
          <span className="close-icon">X</span>
        </button>
      </div>
      
      <form onSubmit={handleSubmit} className="note-form">
        <div style={{ position: "relative" }}>
          <textarea
            className="sticky-input"
            style={{ width: "100%" }}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="What's on your mind?"
            required
            maxLength={150}
            disabled={isSubmitting}
          />
          <div style={{ textAlign: "right", fontSize: "0.8rem", color: "#64748b", marginTop: "4px", fontStyle: "italic" }}>
            {content.length}/150
          </div>
        </div>
        
        <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", marginTop: "1rem" }}>
          <input
            type="text"
            className="sticky-input"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            placeholder="Your name (optional)"
            maxLength={30}
            disabled={isSubmitting}
            style={{ flex: 1, minWidth: "200px" }}
          />
          
          <div className="color-picker" style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <Palette size={20} color="#64748b" />
            <div style={{ display: "flex", gap: "0.4rem" }}>
              {PRESET_COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  className={`color-btn ${color === c ? "selected" : ""}`}
                  style={{ backgroundColor: c }}
                  onClick={() => setColor(c)}
                  disabled={isSubmitting}
                  aria-label={`Select color ${c}`}
                />
              ))}
              <div className="color-picker-wrapper">
                <input
                  type="color"
                  value={color.startsWith("#") ? color : "#ffffff"}
                  onChange={(e) => setColor(e.target.value)}
                  className="color-input"
                  title="Choose custom color"
                  disabled={isSubmitting}
                />
              </div>
            </div>
          </div>
        </div>

        <button type="submit" disabled={isSubmitting || !content.trim()} className="submit-button" style={{ marginTop: "1rem" }}>
          {isSubmitting ? (
            <>
              <Loader2 className="animate-spin" size={20} />
              <span>Sticking...</span>
            </>
          ) : (
            <>
              <Send size={20} />
              <span>Stick to Wall</span>
            </>
          )}
        </button>
      </form>
    </div>
  )
}
